// 1. std::unique_ptr (Exclusive Ownership)
auto p1 = std::make_unique<int>(100);

if (p1) {
    *p1 = 42;
}

// Transfer ownership (move semantics)
std::unique_ptr<int> p2 = std::move(p1);

if (!p1) {
    // p1 is now empty
}

int* raw_ptr = p2.get();

// Custom deleter example (used for RAII of handles)
auto custom_del = [](int* r) { delete[] r; };
std::unique_ptr<int[], decltype(custom_del)>
    p3(new int[5], custom_del);


// 2. std::shared_ptr (Shared Ownership, Reference Counting)
struct Data {};
auto s1 = std::make_shared<Data>();

// s1.use_count() == 1
{
    std::shared_ptr<Data> s2 = s1;
    // s1.use_count() == 2
    s2.reset(); // Decrements count (now 1)
}

// Access
Data& ref = *s1;

// 3. std::weak_ptr (Non-Owning Reference)
std::weak_ptr<Data> w1 = s1;

s1.reset(); // Data is destroyed (count drops to 0)

// Check if resource still exists
if (auto locked = w1.lock()) {
    // This block will not execute
}
// Prevents circular references in complex structures
